import React, { useRef, useEffect } from "react";
import * as tf from "@tensorflow/tfjs-core";
import "@tensorflow/tfjs-backend-webgl";
import * as poseDetection from "@tensorflow-models/pose-detection";
import Webcam from "react-webcam";
import "./App.css";

function App() {
  const webcamRef = useRef(null);
  const canvasRef = useRef(null);
  const videoConstraints = {
  width: 640,
  height: 480,
  facingMode: "user" // Forces the front/selfie camera
};
  const MOVENET_CONNECTIONS = [
  [0, 1], [0, 2], [1, 3], [2, 4],     // Face (Nose to Eyes to Ears)
  [5, 6],                              // Shoulders
  [5, 7], [7, 9],                      // Left Arm (Shoulder-Elbow-Wrist)
  [6, 8], [8, 10],                     // Right Arm
  [5, 11], [6, 12], [11, 12],          // Torso (Shoulders to Hips)
  [11, 13], [13, 15],                  // Left Leg (Hip-Knee-Ankle)
  [12, 14], [14, 16]                   // Right Leg
];


    const runPoseDetection = async () => {
    // 1. ADD THIS LINE: Wait for TFJS to be ready
    await tf.ready();

    // Optional: Explicitly set the backend to WebGL if WebGPU is acting up
    await tf.setBackend('webgl');

    const detector = await poseDetection.createDetector(
      poseDetection.SupportedModels.MoveNet,
      { modelType: poseDetection.movenet.modelType.SINGLEPOSE_LIGHTNING }
    );

    setInterval(() => {
      detect(detector);
    }, 100);
  };

  const detect = async (detector) => {
  if (webcamRef.current && webcamRef.current.video.readyState === 4) {
    const video = webcamRef.current.video;
    const { videoWidth, videoHeight } = video;

    // Set internal canvas resolution to match video stream
    if (canvasRef.current.width !== videoWidth) {
      canvasRef.current.width = videoWidth;
      canvasRef.current.height = videoHeight;
    }

    const poses = await detector.estimatePoses(video);
    const ctx = canvasRef.current.getContext("2d");
    
    // Call your draw function
    drawCanvas(poses, ctx);
  }
};


  const drawCanvas = (poses, ctx) => {
  ctx.clearRect(0, 0, canvasRef.current.width, canvasRef.current.height);

  poses.forEach(({ keypoints }) => {
    // --- 1. Draw the Lines (Skeleton) ---
    ctx.strokeStyle = "aqua";
    ctx.lineWidth = 4;

    MOVENET_CONNECTIONS.forEach(([i, j]) => {
      const kp1 = keypoints[i];
      const kp2 = keypoints[j];

      // Only draw the line if both points are confident
      if (kp1.score > 0.3 && kp2.score > 0.3) {
        ctx.beginPath();
        ctx.moveTo(kp1.x, kp1.y);
        ctx.lineTo(kp2.x, kp2.y);
        ctx.stroke();
      }
    });

    // --- 2. Draw the Dots (Joints) ---
    keypoints.forEach((kp) => {
      if (kp.score > 0.3) {
        ctx.beginPath();
        ctx.arc(kp.x, kp.y, 5, 0, 2 * Math.PI);
        ctx.fillStyle = "white";
        ctx.fill();
      }
    });
  });
};

  useEffect(() => { runPoseDetection(); }, []);

  return (
  <div style={{ 
    position: "relative", 
    width: "640px", 
    height: "480px", 
    margin: "auto",
    border: "2px solid red" // This helps you see the outer container
  }}>
    <Webcam
  ref={webcamRef}
  videoConstraints={videoConstraints}
  onUserMediaError={(err) => console.error("Webcam Error: ", err)}
  style={{ position: "absolute", zIndex: 1 }}
/>
    <canvas
      ref={canvasRef}
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        width: 640,
        height: 480,
        zIndex: 10,
        pointerEvents: "none"
      }}
    />
  </div>
);
}

export default App;
